import {ControlGroup} from '@github-ui/control-group'
import {Link} from '@primer/react'

import type {CreateFormV2Payload} from '../types/repo-creation-types'

export function InitializeRepositoryOptionsV2({
  docsUrls,
  addReadme,
  setAddReadme,
}: {
  docsUrls: CreateFormV2Payload['docsUrls']
  addReadme: boolean
  setAddReadme: (newVal: boolean) => void
}) {
  return (
    <ControlGroup>
      <ControlGroup.Item>
        <ControlGroup.Title className="fgColor-default" id="add-readme">
          Add README
        </ControlGroup.Title>
        <ControlGroup.Description>
          READMEs can be used as longer descriptions.{' '}
          <Link href={docsUrls.readme} target="_blank" inline muted>
            Learn more about READMEs
          </Link>
        </ControlGroup.Description>
        <ControlGroup.ToggleSwitch
          aria-labelledby="add-readme"
          checked={addReadme}
          onClick={e => {
            e.preventDefault()
            setAddReadme(!addReadme)
          }}
        />
      </ControlGroup.Item>
      <ControlGroup.Item>
        <ControlGroup.Title className="fgColor-default">Add .gitignore</ControlGroup.Title>
        <ControlGroup.Description>
          .gitignore tells git which files not to track.{' '}
          <Link href={docsUrls.gitignore} target="_blank" inline muted>
            Learn more about ignoring files
          </Link>
        </ControlGroup.Description>
        <ControlGroup.Custom>Dropdown coming soon</ControlGroup.Custom>
      </ControlGroup.Item>
      <ControlGroup.Item>
        <ControlGroup.Title className="fgColor-default">Add license</ControlGroup.Title>
        <ControlGroup.Description>
          Licenses explain how others can use your code.{' '}
          <Link href={docsUrls.license} target="_blank" inline muted>
            Learn more about licenses
          </Link>
        </ControlGroup.Description>
        <ControlGroup.Custom>Dropdown coming soon</ControlGroup.Custom>
      </ControlGroup.Item>
    </ControlGroup>
  )
}

try{ InitializeRepositoryOptionsV2.displayName ||= 'InitializeRepositoryOptionsV2' } catch {}