import {FormControl, Textarea} from '@primer/react'
import {useEffect} from 'react'

const MAX_LENGTH = 350

export function DescriptionV2({
  description,
  onDescriptionChange,
  isValid,
  setIsValid,
}: {
  description: string
  onDescriptionChange: (value: string) => void
  isValid: boolean
  setIsValid: (isValid: boolean) => void
}) {
  useEffect(() => {
    setIsValid(description.length <= MAX_LENGTH)
  }, [description.length, setIsValid])

  return (
    <FormControl>
      <FormControl.Label>Description</FormControl.Label>
      <FormControl.Caption>
        {description.length} / {MAX_LENGTH} characters
      </FormControl.Caption>
      <Textarea
        block
        resize="vertical"
        rows={3}
        value={description}
        onChange={e => onDescriptionChange(e.target.value)}
        validationStatus={isValid ? undefined : 'error'}
      />
      {!isValid && (
        <FormControl.Validation variant="error">
          Description may not be longer than {MAX_LENGTH} characters
        </FormControl.Validation>
      )}
    </FormControl>
  )
}

try{ DescriptionV2.displayName ||= 'DescriptionV2' } catch {}